def count_palindrome_positions(S):
    N = len(S)
    count = 0
    for i in range(N + 1):
        for j in range(N + 1):
            if S[:i] + S[i:] == (S[:i] + S[i:])[::-1]:
                count += 1
    return count

def main():
    T = int(input())
    results = []
    for _ in range(T):
        S = input()
        results.append(count_palindrome_positions(S))
